const AUTO: Readonly<Record<Os, ThemeName>> = { windows: 'windows7', macos: 'macos', linux: 'ubuntu', other: 'ubuntu' }

/** The theme for a setting (`auto` or a theme name) on an OS; anything unknown behaves as `auto`. */
